import matplotlib.pyplot as plt
import numpy as np


def plot_attention_lines_horizontal(tokens, attention_matrix, max_links=100, head=None):
    """
    Vẽ attention giữa các token theo chiều ngang (tokens nằm trên trục X).

    Parameters:
        tokens: List[str]
            Danh sách token (query và key giống nhau)
        attention_matrix: np.ndarray
            Ma trận attention (shape: seq_len x seq_len hoặc [num_heads, seq_len, seq_len])
        max_links: int
            Số liên kết attention mạnh nhất sẽ được vẽ
        head: int | None
            Nếu có nhiều head, chỉ định head nào để vẽ
    """
    if attention_matrix.ndim == 3:
        if head is None:
            raise ValueError("Vui lòng chỉ định head nếu attention có nhiều head.")
        attention_matrix = attention_matrix[head]

    seq_len = len(tokens)
    assert attention_matrix.shape == (seq_len, seq_len), "Attention matrix không khớp với số token."

    fig, ax = plt.subplots(figsize=(max(10, seq_len * 0.3), 4))
    # fig, ax = plt.subplots(figsize=(min(30, seq_len * 0.15), 6))
    ax.axis('off')

    # Vẽ token ở hai hàng: trên (query) và dưới (key)
    for i, token in enumerate(tokens):
        # ax.text(i, 1.05, token, ha='center', va='bottom', rotation=90, fontsize=10)
        # ax.text(i, -0.05, token, ha='center', va='top', rotation=90, fontsize=10)

        ax.text(i, 1.15, token, ha='center', va='bottom', rotation=90, fontsize=8, color='gray')  # index (gốc)
        ax.text(i, 1.05, str(i * 10), ha='center', va='bottom', rotation=90, fontsize=8)  # query token
        ax.text(i, -0.05, str(i * 10), ha='center', va='top', rotation=90, fontsize=8)   # key token


    # Tìm top attention links
    attention_flat = attention_matrix.flatten()
    top_indices = attention_flat.argsort()[-max_links:][::-1]
    max_weight = attention_flat[top_indices[0]]

    for index in top_indices:
        i = index // seq_len  # query
        j = index % seq_len  # key
        weight = attention_matrix[i, j]
        alpha = weight / max_weight

        ax.plot([i, j], [1, 0], color='purple', alpha=alpha, linewidth=1 + 2 * alpha)

    ax.set_xlim(-1, seq_len)
    ax.set_ylim(-0.2, 1.2)
    plt.title("Attention Lines Between Tokens (Horizontal View)", fontsize=14)
    plt.tight_layout()
    plt.show()

